function onPluginMessage(plugin, data) {
  if (plugin !== 'action_command_notification') return;
  if (data.message && popupsEnabled()) {
    new PNotify({
      title: gettext('Printer Notification'),
      text: data.message,
      hide: false,
    });
  }
}

