import yaml from 'js-yaml';

const getArtifact = (path) =>
  fetch(`/api/2.0/mlflow-artifacts/artifacts/${path}`).then((r) => r.text());

function fetchLoggedModelMetadata(path) {
  getArtifact(`${path}/MLmodel`).then((response) => {
    const parsedJson = yaml.load(response);
    if (parsedJson.signature) {
      render(parsedJson.signature);
    }
  });
}

global.confirmPrompt = function (message, title) {
  var dfd = $.Deferred();
  message = $('<div>', {width: 400, html: message});
  new ConfirmPopup(title || 'Please confirm', message, function (confirmed) {
    if (confirmed) dfd.resolve();
  });
};

