Listing.prototype.add_tag_handler = function (name, handler) {
  if (this.navobj.getparam(name + 'filter') !== undefined) {
    var text = this.navobj.getparam(name + 'filter');
    $('#taglist').append(this.make_tag(text, name));
  }
};

Listing.prototype.make_tag = function (text, type) {
  var $tag = $('<a />', {
    name: type,
    'class': 'btn btn-xs',
    html: ' ' + text,
  });
  return $tag;
};
